SELECT * FROM banners b WHERE position = #{position} AND visible = true AND (start_date IS NULL OR start_date <= NOW()) AND (end_date IS NULL OR end_date >= NOW()) AND ( NOT EXISTS (SELECT 1 FROM banner_channels bc WHERE bc.banner_id = b.id)
OR EXISTS ( SELECT 1 FROM banner_channels bc WHERE bc.banner_id = b.id AND bc.channel_id = #{channelId}::uuid )
) ORDER BY display_order ASC, created_at DESC

SELECT channel_id::text
FROM banner_channels
WHERE banner_id = #{bannerId}

SELECT *
FROM banners



        AND (
        name ILIKE CONCAT('%', #{keyword}, '%')
        OR description ILIKE CONCAT('%', #{keyword}, '%')
        )



        AND position = #{position}



        AND visible = #{visible}



ORDER BY display_order ASC, created_at DESC
